// kinds 30550-30554 fa:Kanban* validator (evenflow EFB-24).
//
// This file is the contract between two repos. Evenflow builds and signs these
// events; the gateway only checks them. A change on either side that isn't
// mirrored is a silent publish failure — evenflow keeps stamping
// substrate_event_id NULL and nobody notices until someone asks why a public
// board has no substrate history.
//
// The GOLDEN fixtures below were generated by running evenflow's real builders
// (src/lib/audience/audience-events.ts, buildKanban*) with fixed ids and a
// fixed createdAt — not hand-written here. If evenflow changes a tag or a
// content field, these stop matching and this suite goes red, which is the
// entire point. Regenerate them in the same PR as the builder change.
//
// Signature and canonical id are NOT this validator's job (requireSignedEvent
// handles those upstream), so nothing here signs anything.

import { describe, expect, it } from "vitest";
import { blake3ContentTag } from "../lib/blake3-tag";
import {
  KIND_KANBAN_BOARD,
  KIND_KANBAN_COMMENT,
  KIND_KANBAN_ISSUE,
  KIND_KANBAN_SPRINT,
  KIND_KANBAN_STATUS_CHANGE,
  validateKanbanPlaintextEvent,
  type KanbanEventLike,
} from "../kanban-plaintext-validator";

