/** Rebuild an event with one tag replaced or removed (undefined = remove). */
const withTag = (base: KanbanEventLike, name: string, value?: string): KanbanEventLike => {
  const tags = base.tags.filter((t) => t[0] !== name);
  if (value !== undefined) tags.push([name, value]);
  return { ...base, tags };
};

/** Replace content and re-hash, so only the field under test is wrong. */
const withContent = (base: KanbanEventLike, over: Record<string, unknown>): KanbanEventLike => {
  const content = JSON.stringify({ ...JSON.parse(base.content), ...over });
  return withTag({ ...base, content }, "blake3", blake3ContentTag(content));
};

describe("golden events from evenflow's builders", () => {
  // The drift guard. These blake3 tags were produced by evenflow, not by this
  // file — if they still match what blake3ContentTag computes here, the two
  // repos agree on content serialization byte-for-byte.
  it.each(Object.entries(GOLDEN))("%s: blake3 tag matches its content", (_name, ev) => {
    const tag = ev.tags.find((t) => t[0] === "blake3")?.[1];
    expect(tag).toBe(blake3ContentTag(ev.content));
  });

  it.each(Object.entries(GOLDEN))("%s: validates", (_name, ev) => {
    const res = validateKanbanPlaintextEvent(ev);
    expect(res.ok).toBe(true);
  });

  it("reports the parsed identity for each kind", () => {
    const board = validateKanbanPlaintextEvent(GOLDEN["board"]!);
    expect(board.ok && board.value).toMatchObject({
      kind: KIND_KANBAN_BOARD,
      type: "KanbanBoard",
      boardId: BOARD,
      dTag: BOARD,
      deleted: false,
    });

    const issue = validateKanbanPlaintextEvent(GOLDEN["issue"]!);
    expect(issue.ok && issue.value).toMatchObject({
      kind: KIND_KANBAN_ISSUE,
      dTag: ISSUE,
      sprintId: SPRINT,
    });

    const comment = validateKanbanPlaintextEvent(GOLDEN["comment"]!);
    expect(comment.ok && comment.value).toMatchObject({
      kind: KIND_KANBAN_COMMENT,
      dTag: COMMENT,
      issueId: ISSUE,
    });

    const sc = validateKanbanPlaintextEvent(GOLDEN["statusChange"]!);
    expect(sc.ok && sc.value).toMatchObject({
      kind: KIND_KANBAN_STATUS_CHANGE,
      dTag: STATUS_CHANGE,
      issueId: ISSUE,
    });

    const sprint = validateKanbanPlaintextEvent(GOLDEN["sprint"]!);
    expect(sprint.ok && sprint.value).toMatchObject({
      kind: KIND_KANBAN_SPRINT,
      dTag: SPRINT,
      sprintId: SPRINT,
    });
  });
});

describe("kind allowlist", () => {
  it("rejects a kind outside 30550-30554", () => {
    const res = validateKanbanPlaintextEvent({ ...GOLDEN["issue"]!, kind: 30560 });
    expect(res).toMatchObject({ ok: false });
    expect(res.ok === false && res.error).toContain("30550-30554");
  });

  // The encrypted variants never come through here: private boards gift-wrap
  // and publish via /v0/audience/raw/publish-wraps.
  it("rejects an encrypted kanban kind", () => {
    const res = validateKanbanPlaintextEvent({ ...GOLDEN["issue"]!, kind: 30556 });
    expect(res).toMatchObject({ ok: false });
  });
});

describe("shared envelope", () => {
  it.each(["fa:context", "fa:board", "d", "alt", "blake3"])("requires %s", (tag) => {
    const res = validateKanbanPlaintextEvent(withTag(GOLDEN["issue"]!, tag, undefined));
    expect(res).toMatchObject({ ok: false });
  });

  it("rejects a wrong fa:context", () => {
    const res = validateKanbanPlaintextEvent(
      withTag(GOLDEN["issue"]!, "fa:context", "https://example.com/ns/v1"),
    );
    expect(res.ok === false && res.error).toContain("fa:context");
  });

  it("rejects an empty fa:board", () => {
    const res = validateKanbanPlaintextEvent(withTag(GOLDEN["issue"]!, "fa:board", ""));
    expect(res.ok === false && res.error).toContain("fa:board");
  });

  // Catches a re-serialized or tampered body without re-reading every field.
  it("rejects a blake3 that does not match content", () => {
    const res = validateKanbanPlaintextEvent(
      withTag(GOLDEN["issue"]!, "blake3", "bk-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),
    );
    expect(res.ok === false && res.error).toContain("blake3");
  });

  it("rejects non-JSON content", () => {
    const bad = { ...GOLDEN["issue"]!, content: "not json" };
    const res = validateKanbanPlaintextEvent(withTag(bad, "blake3", blake3ContentTag("not json")));
    expect(res.ok === false && res.error).toContain("valid JSON");
  });

  it("rejects a JSON array as content", () => {
    const arr = "[1,2,3]";
    const res = validateKanbanPlaintextEvent(
      withTag({ ...GOLDEN["issue"]!, content: arr }, "blake3", blake3ContentTag(arr)),
    );
    expect(res.ok === false && res.error).toContain("JSON object");
  });

  it("rejects a wrong content @context", () => {
    const res = validateKanbanPlaintextEvent(
      withContent(GOLDEN["issue"]!, { "@context": "https://example.com" }),
    );
    expect(res.ok === false && res.error).toContain("@context");
  });
});

describe("per-kind shape", () => {
  it("rejects a content @type that does not match the kind", () => {
    const res = validateKanbanPlaintextEvent(
      withContent(GOLDEN["issue"]!, { "@type": "KanbanBoard" }),
    );
    expect(res.ok === false && res.error).toContain("KanbanIssue");
  });

  it.each(["fa:type", "fa:status", "fa:container"])("issue requires %s", (tag) => {
    const res = validateKanbanPlaintextEvent(withTag(GOLDEN["issue"]!, tag, undefined));
    expect(res).toMatchObject({ ok: false });
  });

  it("comment requires fa:issue", () => {
    const res = validateKanbanPlaintextEvent(withTag(GOLDEN["comment"]!, "fa:issue", undefined));
    expect(res).toMatchObject({ ok: false });
  });

  it("board requires fa:slug", () => {
    const res = validateKanbanPlaintextEvent(withTag(GOLDEN["board"]!, "fa:slug", undefined));
    expect(res).toMatchObject({ ok: false });
  });

  it.each(["fa:sprint", "fa:status"])("sprint requires %s", (tag) => {
    const res = validateKanbanPlaintextEvent(withTag(GOLDEN["sprint"]!, tag, undefined));
    expect(res).toMatchObject({ ok: false });
  });

  // These kinds are parameterized-replaceable, so `d` decides what a republish
  // REPLACES. A board event keyed on anything but its board id would overwrite
  // an unrelated address.
  it("board d tag must equal fa:board", () => {
    const res = validateKanbanPlaintextEvent(withTag(GOLDEN["board"]!, "d", "some-other-id"));
    expect(res.ok === false && res.error).toContain("fa:board");
  });

  it("sprint d tag must equal fa:sprint", () => {
    const res = validateKanbanPlaintextEvent(withTag(GOLDEN["sprint"]!, "d", "some-other-id"));
    expect(res.ok === false && res.error).toContain("fa:sprint");
  });

  // An issue's d tag is its own id, which appears in no other tag — so it is
  // only required to be present and non-empty.
  it("accepts an issue whose d tag is its own id", () => {
    const res = validateKanbanPlaintextEvent(GOLDEN["issue"]!);
    expect(res.ok && res.value.dTag).toBe(ISSUE);
  });
});

describe("tombstones", () => {
  // evenflow publishes deletions as deleted:true at the entity's OWN address
  // rather than via NIP-09 — a tombstone anywhere else would leave the last
  // live version standing for a replaying consumer.
  it("accepts deleted:true and surfaces it", () => {
    const res = validateKanbanPlaintextEvent(withContent(GOLDEN["issue"]!, { deleted: true }));
    expect(res.ok && res.value.deleted).toBe(true);
  });

  it("rejects a non-boolean deleted", () => {
    const res = validateKanbanPlaintextEvent(withContent(GOLDEN["issue"]!, { deleted: "yes" }));
    expect(res.ok === false && res.error).toContain("deleted");
  });
});
